// Normalizador multi-banco -> esquema BANCOS_MOV (v5)
// Soporta dos formatos de origen:
//  A) Archivo CON encabezado real en texto (ej. "Fecha", "Descripcion", "Valor")
//     -- la cuenta se identifica por el NOMBRE DEL ARCHIVO (patron de siempre,
//     ej. BC-AHO-8985_2026-07.xlsx). Se lee via 'Leer CSV/XLSX'.
//  B) "Extracto plano" de Bancolombia SIN encabezado, 10 columnas fijas:
//     cuenta_raw, oficina, _, fecha AAAAMMDD, _, valor, codigo_operacion,
//     descripcion, estado, _ -- NO requiere renombrar el archivo: la cuenta
//     se identifica buscando cuenta_raw en CAT_BANCOS.numero.
//     Para este formato se usa un segundo nodo 'Leer CSV sin encabezado
//     (plano)' (extractFromFile con headerRow=false) sobre una segunda
//     descarga del mismo archivo: con headerRow=false n8n entrega cada fila
//     con claves posicionales "0".."9", sin inventarse nombres de columna
//     -- evita el problema de intentar leer el binario a mano (rompe si
//     n8n guarda binarios en filesystem en vez de memoria) y evita que
//     las columnas vacias de este extracto colisionen entre si si se
//     intentara reconstruir la fila de encabezado de 'Leer CSV/XLSX'.

const catBancos = $('Leer CAT_BANCOS').all().map(i => i.json);

function parseValor(v) {
  if (typeof v === 'number') return v;
  let s = String(v || '').replace(/[A-Za-z$\s ]/g, '');
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}
function parseFecha(v) {
  if (v instanceof Date) return v.toISOString().slice(0,10);
  const s = String(v || '').trim();
  if (/^\d{8}$/.test(s)) return s.slice(0,4) + '-' + s.slice(4,6) + '-' + s.slice(6,8); // AAAAMMDD (extracto plano Bancolombia)
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000).toISOString().slice(0,10);
  }
  if (/^\d+$/.test(s)) { const n = parseInt(s); if (n > 20000 && n < 80000) return new Date(Date.UTC(1899,11,30) + n*86400000).toISOString().slice(0,10); }
  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2,'0') + '-' + m[3].padStart(2,'0');
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})/);
  if (m) return m[3] + '-' + m[2].padStart(2,'0') + '-' + m[1].padStart(2,'0');
  return s.slice(0,10);
}
function pick(row, patterns) {
  for (const pat of patterns) {
    for (const k of Object.keys(row)) {
      if (pat.test(k)) return row[k];
    }
  }
  return '';
}
function clasificar(desc, valor, refTexto) {
  const d = String(desc || '').toUpperCase();
  if (d.includes('4X1000') || d.includes('IMPTO GOBIERNO')) return ['IMPUESTO', '4X1000'];
  if (d.includes('ABONO INTERESES')) return ['INGRESO', 'INTERES_GANADO'];
  if (d.includes('PRESTAMO') || d.includes('PAGOPTMO')) return ['EGRESO', 'PAGO_CREDITO'];
  if (d.includes('INTERES')) return ['EGRESO', 'INTERES_CREDITO'];
  if (d.includes('COMISION') || d.includes('CUOTA MANEJO') || d.includes('IVA COMIS') || d.includes('SWIFT') || d.includes('FEE COLLEC') || d.includes('COBRO MENSUAL')) return ['GASTO_BANCARIO', 'COMISION'];
  if ((d.includes('TRANSFERENCIA CTA SUC') || d.includes('TRASLADO')) && /(3762|8985|4335|6614|9030|3826)/.test(d + ' ' + String(refTexto || ''))) return ['TRASLADO', 'TRASLADO_INTERNO'];
  if (d.includes('NOMIN') || d.includes('SALARIO')) return ['EGRESO', 'NOMINA']; // cubre "PAGO A NOMIN <nombre truncado>" del extracto plano
  if (d.includes('GOOGLE') || d.includes('ADS') || d.includes('META PLATFORMS')) return ['EGRESO', 'PUBLICIDAD'];
  if (d.includes('PAGO DE PROV') && valor > 0) return ['INGRESO', 'REINTEGRO_PROVEEDOR']; // reintegro/ajuste de un proveedor (envio fallido, cancelacion de pedido, etc.) -- confirmado por Milena 5 oct 2026
  if (d.includes('PAGO PSE') && valor < 0) return ['EGRESO', 'PAGO_PROVEEDOR'];
  if ((d.includes('DESDE NEQUI') || d.includes('PAGO LLAVE') || d.includes('CONSIGNACION')) && valor > 0) return ['INGRESO', 'VENTA'];
  if (d.includes('TRANSFERENCIA EXT DE') && valor > 0) return ['INGRESO', 'TRANSFERENCIA_INTL'];
  if (valor > 0) return ['INGRESO', 'POR_CLASIFICAR'];
  return ['EGRESO', 'POR_CLASIFICAR'];
}
function col(row, idx) {
  if (row == null) return '';
  if (row[idx] !== undefined) return row[idx];
  if (row[String(idx)] !== undefined) return row[String(idx)];
  return '';
}

const filasPlanoRaw = (function () {
  try { return $('Leer sin encabezado (plano)').all().map(i => i.json); } catch (e) { return []; }
})();
const esPlano = filasPlanoRaw.length > 0
  && /^\d{8}$/.test(String(col(filasPlanoRaw[0], 3) || '').trim())
  && /^-?\d+(\.\d+)?$/.test(String(col(filasPlanoRaw[0], 5) || '').trim());

let seq = Date.now();
const out = [];

if (esPlano) {
  for (const row of filasPlanoRaw) {
    const cuentaRaw = String(col(row, 0) || '').trim();
    const fechaRaw = col(row, 3);
    const valorRaw = col(row, 5);
    const codigoOp = String(col(row, 6) || '').trim();
    const desc = col(row, 7);
    if (!cuentaRaw || !desc) continue;
    const banco = catBancos.find(b => String(b.numero || '').trim() === cuentaRaw);
    if (!banco) {
      throw new Error('Cuenta "' + cuentaRaw + '" no esta registrada en CAT_BANCOS.numero -- agregala para la cuenta correcta antes de reintentar esta carga.');
    }
    const valor = parseValor(valorRaw);
    const [tipo, cat] = clasificar(desc, valor, codigoOp);
    out.push({ json: {
      id_mov: 'MOV-' + (seq++).toString().slice(-9),
      fecha: parseFecha(fechaRaw),
      cuenta: banco.codigo,
      descripcion: String(desc).trim(),
      referencia: codigoOp,
      moneda: banco.moneda || 'COP',
      valor: valor,
      tipo: tipo,
      categoria: cat
    }});
  }
} else {
  const rawRows = $('Leer CSV/XLSX').all().map(i => i.json);
  const filename = $('Nuevo extracto en Drive (carpeta EXTRACTOS_ENTRADA)').first().json.name || '';
  const cuentaMatch = filename.match(/(BC-CTE-3762|BC-AHO-8985|DV-AHO-4335|DV-CTE-6614|BA-9030|BC-PAN-USD)/i);
  if (!cuentaMatch) throw new Error('El nombre del archivo debe incluir el codigo de cuenta de CAT_BANCOS. Ej: BC-CTE-3762_2026-07.xlsx o BC-PAN-USD_junio.xlsx');
  const cuenta = cuentaMatch[1].toUpperCase();
  const moneda = cuenta === 'BC-PAN-USD' ? 'USD' : 'COP';
  for (const r of rawRows) {
    const fechaRaw = pick(r, [/^fecha( aplicaci)?/i, /^fecha$/i]);
    const desc = pick(r, [/descrip/i]);
    const valorRaw = pick(r, [/^valor$/i, /valor/i]);
    if (!desc && !valorRaw) continue;
    const ref1 = pick(r, [/referencia 1/i, /n[uu]mero de la transacci/i, /^referencia$/i]);
    const ref2 = pick(r, [/referencia 2/i]);
    const valor = parseValor(valorRaw);
    if (valor === 0 && !desc) continue;
    const [tipo, cat] = clasificar(desc, valor, [ref1, ref2].join(' '));
    out.push({ json: {
      id_mov: 'MOV-' + (seq++).toString().slice(-9),
      fecha: parseFecha(fechaRaw),
      cuenta: cuenta,
      descripcion: String(desc).trim(),
      referencia: [ref1, ref2].map(x => String(x || '').trim()).filter(x => x && x !== '- -' && x !== '--').join(' | '),
      moneda: moneda,
      valor: valor,
      tipo: tipo,
      categoria: cat
    }});
  }
}

if (out.length === 0) throw new Error('El archivo no produjo movimientos: revisar el formato (extracto plano sin encabezado, o encabezados reales con nombre de archivo correcto).');
return out;

parameters.query:
insert into bancos_mov (id_mov, fecha, cuenta, descripcion, referencia, moneda, valor, tipo, categoria, origen)
values ($1,$2,$3,$4,$5,$6,$7,$8,$9,'EXTRACTO')
on conflict (id_mov) do nothing;

